TYPE.TEST:


SetFunctionName("Soa4Vector3()");

Soa4Vector3 v;

Validate( true ); // Take address of v so that it is referenced


SetFunctionName("Soa4Vector3(const Soa4Vector3&)");

Soa4Vector3 ref( mA );

Validate( IsEqual( ref, mA ) );


SetFunctionName("Soa4Vector3(Soa4Float)");

Soa4Vector3 ref( Soa4FloatFromFloat( 1.0f ) );

Validate( IsEqual( ref, mOne ) );



SetFunctionName("Soa4Vector3(VectorIntrinsic)");

VectorIntrinsic vx, vy, vz;
vx = Soa4FloatFromFloat( 1.0f ).mV;
vy = Soa4FloatFromFloat( 1.0f ).mV;
vz = Soa4FloatFromFloat( 1.0f ).mV;

Soa4Vector3 ref( vx, vy, vz );

Validate( IsEqual( ref, mOne ) );


SetFunctionName("Soa4Vector3 operator=(const Soa4Vector3&)");

Soa4Vector3 ref( mZero );
Validate( !IsEqual( ref, mOne ) );

ref = mOne;

Validate( IsEqual( ref, mOne ) );
Validate( &ref.x != &mOne.x && &ref.y != &mOne.y && &ref.z != &mOne.z );


SetFunctionName("X()");

Soa4Vector3 ref( mNegOne );

const Soa4Float& cx = ref.X();
Validate( IsEqual( cx, ref.x ) );

Soa4Float& x = ref.X();

x = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("Y()");

Soa4Vector3 ref( mNegOne );

const Soa4Float& cy = ref.Y();
Validate( IsEqual( cy, ref.y ) );

Soa4Float& y = ref.Y();

y = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat( -1.0f ) ) );


SetFunctionName("Z()");

Soa4Vector3 ref( mNegOne );

const Soa4Float& cz = ref.Z();
Validate( IsEqual( cz, ref.z ) );

Soa4Float& z = ref.Z();

z = Soa4FloatFromFloat( 1.0f );

Validate( !IsEqual( ref, mOne ) );
Validate( IsEqual( ref.x, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( ref.z, Soa4FloatFromFloat(  1.0f ) ) );


SetFunctionName("Soa4Vector3FromVector3(Vector3::InParam v)");

Vector3 v( 1.0f, -1.0f, 2.0f );
Soa4Vector3 sv = Soa4Vector3FromVector3( v );
Validate( IsEqual( sv.x, Soa4FloatFromFloat(  1.0f ) ) );
Validate( IsEqual( sv.y, Soa4FloatFromFloat( -1.0f ) ) );
Validate( IsEqual( sv.z, Soa4FloatFromFloat(  2.0f ) ) );


SetFunctionName("Soa4Vector3FromVector3(Vector3::InParam v0, Vector3::InParam v1, Vector3::InParam v2, Vector3::InParam v3)");

// These are the same values as in the member vector "mA"
Vector3 v0( -1.0f, 5.0f, 0.25f );
Vector3 v1(  2.0f, 3.0f, 1.0f );
Vector3 v2(  3.0f, 3.0f, 3.0f );
Vector3 v3( -4.0f, 1.0f, -10.0f );

Soa4Vector3 sv = Soa4Vector3FromVector3( v0, v1, v2, v3 );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Soa4Vector3FromVector3(const Vector3*)");

// These are the same values as in the member vector "mA"
Vector3 v[4] = {
    Vector3( -1.0f, 5.0f, 0.25f ),
    Vector3(  2.0f, 3.0f, 1.0f ),
    Vector3(  3.0f, 3.0f, 3.0f ),
    Vector3( -4.0f, 1.0f, -10.0f )
};

Soa4Vector3 sv = Soa4Vector3FromVector3( v );

Validate( IsEqual( sv, mA ) );


SetFunctionName("Vector3FromSoa4Vector3(Soa4Vector3::InParam, Vector3& v0, Vector3& v1, Vector3& v2, Vector3& v3)");
Vector3 v0, v1, v2, v3;
Vector3 rv0( -1.0f, 5.0f, 0.25f );
Vector3 rv1(  2.0f, 3.0f, 1.0f );
Vector3 rv2(  3.0f, 3.0f, 3.0f );
Vector3 rv3( -4.0f, 1.0f, -10.0f );

Vector3FromSoa4Vector3( mA, v0, v1, v2, v3 );
Validate( IsEqual( v0, rv0 ) );
Validate( IsEqual( v1, rv1 ) );
Validate( IsEqual( v2, rv2 ) );
Validate( IsEqual( v3, rv3 ) );


SetFunctionName("Vector3FromSoa4Vector3(Soa4Vector3::InParam, Vector3* v)");
Vector3 v[4];
Vector3 rv0( -1.0f, 5.0f, 0.25f );
Vector3 rv1(  2.0f, 3.0f, 1.0f );
Vector3 rv2(  3.0f, 3.0f, 3.0f );
Vector3 rv3( -4.0f, 1.0f, -10.0f );

Vector3FromSoa4Vector3( mA, v );
Validate( IsEqual( v[0], rv0 ) );
Validate( IsEqual( v[1], rv1 ) );
Validate( IsEqual( v[2], rv2 ) );
Validate( IsEqual( v[3], rv3 ) );


SetFunctionName("operator *= (Soa4Vector3& v, Soa4Float::InParam a)");

