SetFunctionName("Dot(Soa4Vector3::InParam a, Soa4Vector3::InParam b)");

{
    Soa4Float ref = Soa4FloatFromFloats( 15.375f, 18.0f, -13.5f, -1.0f );
    Soa4Float dot = Dot( mA, mB );
    Validate( IsEqual( dot, ref ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Cross(Soa4Vector3::InParam a, Soa4Vector3::InParam b)");

{
    Soa4Float refI = Soa4FloatFromFloats(  6.25f, -30.0f, -13.5f, 13.0 );
    Soa4Float refJ = Soa4FloatFromFloats(   4.0f,  27.0f, -22.5f, 82.0 );
    Soa4Float refK = Soa4FloatFromFloats( -55.0f, -21.0f,  36.0f,  3.0 );
    Soa4Vector3 ref( refI, refJ, refK );

    Soa4Vector3 cross = Cross( mA, mB );

    Validate( IsEqual( cross, ref ) );

    Validate( IsEqualWithEpsilon( Dot( mA, cross ), Soa4FloatFromFloat( 0.0f ) ) 
        && IsEqualWithEpsilon( Dot( mB, cross ), Soa4FloatFromFloat( 0.0f ) ) );
}

