SetFunctionName("Reciprocal(Soa4Vector3::InParam a)");

{
    Soa4Vector3 ref;
    ref.x.mV = Set( 1.0f/10.0f, 1.0f/9.0f, 1.0f/-8.0f, 1.0f/-7.0f );
    ref.y.mV = Set( 1.0f/5.0f, 1.0f/3.0f, 1.0f/4.0f, 1.0f/1.0f );
    ref.z.mV = Set( 1.0f/1.5f, 1.0f/-9.0f, 1.0f/-0.5f, 1.0f/3.0f );

    Soa4Vector3 res = Reciprocal( mB );
    Validate( IsEqualWithEpsilon( res, ref ) );
}


