//-----------------------------------------------------------------------



Soa4Vector3 ref( mA );

Soa4Float mag = Soa4FloatFromFloats( 5.1051445f,
                    3.7416575f,
                    5.196152f,
                   10.816654f );

Soa4Float invMag = Soa4FloatFromFloats( 0.19588085f,
                    0.26726124f,
                    0.19245009f,
                    0.09245003f );

ref *= invMag;

Soa4Float one = Soa4FloatFromFloats( 1.0f, 1.0f, 1.0f, 1.0f );


SetFunctionName("NormalizeFast(Soa4Vector3::InParam v)");

{
    Soa4Vector3 res = NormalizeFast( mA );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NormalizeEstimate(Soa4Vector3::InParam v)");

{
    Soa4Vector3 res = NormalizeEstimate( mA );
    Validate( IsEqualWithEpsilon( res, ref, 0.003f) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one, Soa4FloatFromFloat(0.003f) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("Normalize(Soa4Vector3::InParam v)");

{
    Soa4Vector3 res = Normalize( mA );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NormalizeReturnMagnitude(Soa4Vector3::InParam v, Soa4Vector3& result)");

{
    Soa4Vector3 res;
    Soa4Float testMagnitude = NormalizeReturnMagnitude( mA, res );
    Validate( IsEqualWithEpsilon( res, ref ) );
    Validate( IsEqualWithEpsilon( testMagnitude, mag ) );
    Validate( IsEqualWithEpsilon( Magnitude( res ), one ) );                
    Validate( IsEqualWithEpsilon( mA, Mult( res, mag ) ) );
}

//-----------------------------------------------------------------------

SetFunctionName("CheckedNormalizeReturnMagnitude(Soa4Vector3::InParam v, Soa4Float& magnitude)");

{
    VectorIntrinsic ax = CreateSoa4Float( -1.0f, 0.0f, 3.0f, -4.0f ).mV;
    VectorIntrinsic ay = CreateSoa4Float(  5.0f, 0.0f, 3.0f,  1.0f ).mV;
    VectorIntrinsic az = CreateSoa4Float( 0.25f, 0.0f, 3.0f, -10.0f ).mV;
    Soa4Vector3 vec( ax, ay, az );

    Soa4Float zeroComponentMagnitude = Soa4FloatFromFloats( 5.1051445f,
                    0.0f,
                    5.196152f,
                    10.816654f );

    Soa4Vector3 res;
    Soa4Float testMagnitude = CheckedNormalizeReturnMagnitude( vec, res );
    Soa4Vector3 nonChecked = Normalize( vec );

    Validate( !IsEqual( nonChecked, vec ) );
    Validate( IsEqualWithEpsilon( zeroComponentMagnitude, testMagnitude ) );
    Validate( IsEqualWithEpsilon( vec, Mult( res, testMagnitude ) ) );
}



Soa4Float t = Soa4FloatFromFloats( 0.25f, 0.5f, 0.75f, 1.0f );
Soa4Vector3 ref = Soa4Vector3(
    Soa4FloatFromFloats( 7.75f,   4.5f,  -2.75f, 2.0f ),
    Soa4FloatFromFloats( 3.75f,   2.0f,   0.25f, 2.0f ),
    Soa4FloatFromFloats(  1.4f, -4.45f, -0.275f, 0.3f ) );
Soa4Vector3 normalRef = Normalize( ref );

SetFunctionName("Lerp(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector3 res = Lerp( mB, mC, t );
    Validate( IsEqualWithEpsilon( res, ref ) );
}

//-----------------------------------------------------------------------

SetFunctionName("SLerp(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector3 a( Soa4FloatFromFloat( 1.0f ), Soa4FloatFromFloat( 2.0f ), Soa4FloatFromFloat( 2.3f ) );
    Soa4Vector3 b( Soa4FloatFromFloat( -3.0f ), Soa4FloatFromFloat( 1.0f ), Soa4FloatFromFloat( -3.8f ) );
    Soa4Float slerpT( Soa4FloatFromFloats( 0.75f, 0.75f, 0.75f, 0.75f ) );
    Soa4Vector3 normalA = Normalize( a );
    Soa4Vector3 normalB = Normalize( b );

    Soa4Vector3 output = SLerp( normalA, normalB, slerpT );

    Soa4Vector3 slerpRef( Soa4FloatFromFloat( -0.56233941545710642f ), 
        Soa4FloatFromFloat( 0.65999988092828232f ),
        Soa4FloatFromFloat( -0.50302293780669616f ) );
    Validate( IsEqualWithEpsilon( output, slerpRef, 0.02f ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NLerpEstimate(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector3 res = NLerpEstimate( mB, mC, t );
    Validate( IsEqualWithEpsilon( res, normalRef, 0.003f ) );
}

//-----------------------------------------------------------------------

SetFunctionName("NLerpFast(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector3 res = NLerpFast( mB, mC, t );
