SetFunctionName("NLerp(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Float::InParam t)");

{
    Soa4Vector3 res = NLerp( mB, mC, t );
    Validate( IsEqualWithEpsilon( res, normalRef ) );
