SetFunctionName("Min(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1)");

{
    Soa4Vector3 res = Min( mA, mTwo );
    VectorIntrinsic v[3] = {
        CreateSoa4Float( -1.0f, 2.0f, 2.0f, -4.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 1.0f ).mV,
        CreateSoa4Float( 0.25f, 1.0f, 2.0f, -10.0f ).mV
    };
    Soa4Vector3 ref( v[0], v[1], v[2] );

    Validate( IsEqual( res, ref ) );
}

