SetFunctionName("ClampToNegPosRange(Soa4Vector3::InParam vecToClamp, Soa4Vector3::InParam range)");

{
    VectorIntrinsic r[3] = {
        CreateSoa4Float( 1.0f, 1.0f, 1.0f, 1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 2.0f ).mV,
        CreateSoa4Float( 0.5f, 0.5f, 0.5f, 0.5f ).mV
    };
