    Soa4Vector3 res = ClampToNegPosRange( mA, range );
    VectorIntrinsic v[3] = {
        CreateSoa4Float( -1.0f, 1.0f, 1.0f, -1.0f ).mV,
        CreateSoa4Float( 2.0f, 2.0f, 2.0f, 1.0f ).mV,
