SetFunctionName("AngleBetweenVectors(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1)");

{
    Soa4Vector3 normalizedA = Normalize( mA );
    Soa4Vector3 normalizedB = Normalize( mB );
    Soa4Float refAngle = Dot( normalizedA, normalizedB );
    Soa4Float ref;
    RW_MATH_VPU_ACos( ref.mV, refAngle.mV );

    Soa4Float res = AngleBetweenVectors( mA, mB );
    Validate( IsEqualWithEpsilon( ref, res ) );
}

//-----------------------------------------------------------------------

SetFunctionName("AngleBetweenVectors(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1, Soa4Vector3::InParam windAxis)");

{
    VectorIntrinsic v[] =
    {
        CreateSoa4Float( 0.2672612f, 0.2672612f, 0.2672612f, 0.2672612f ).mV,
        CreateSoa4Float( 0.5345225f, 0.5345225f, 0.5345225f, 0.5345225f ).mV,
        CreateSoa4Float( 0.8017837f, 0.8017837f, 0.8017837f, 0.8017837f ).mV,
        CreateSoa4Float( -0.3810004f, -0.3810004f, -0.3810004f, -0.3810004f ).mV,
        CreateSoa4Float( 0.8890009f, 0.8890009f, 0.8890009f, 0.8890009f ).mV,
        CreateSoa4Float( 0.2540003f, 0.2540003f, 0.2540003f, 0.2540003f ).mV,
        CreateSoa4Float( 5.0f, 5.0f, 5.0f, 5.0f ).mV,
        CreateSoa4Float( 7.0f, 7.0f, 7.0f, 7.0f ).mV,
        CreateSoa4Float( -1.0f, -1.0f, -1.0f, -1.0f ).mV
    };

    Soa4Vector3 v3a( v[0], v[1], v[2] ), v3b( v[3], v[4], v[5] );
    Soa4Vector3 windAxis = Cross( v3a, v3b );
    v3a *= Soa4Float( v[6] );
    v3b *= Soa4Float( v[7] );

    Soa4Float res1 = AngleBetweenVectors( v3a, v3b, windAxis );
    Soa4Float res2 = AngleBetweenVectors( v3a, v3b, windAxis * Soa4Float( v[8] ) );
    Validate(   IsEqualWithEpsilon( res1, Soa4FloatFromFloat( 0.955724f ) ) &&
                IsEqualWithEpsilon( res2, Soa4FloatFromFloat( 5.327461f ) ) );

}

//-----------------------------------------------------------------------

SetFunctionName("CosAngleBetweenNormalizedVectors(Soa4Vector3::InParam v0, Soa4Vector3::InParam v1)");

{
    Soa4Vector3 normalizedA = Normalize( mA );
    Soa4Vector3 normalizedB = Normalize( mB );
    Soa4Float refAngle = Dot( normalizedA, normalizedB );
    Soa4Float res = CosAngleBetweenNormalizedVectors( normalizedA, normalizedB );

    Validate( IsEqual( refAngle, res ) );
}



