SetFunctionName("Select(Soa4MaskScalar::InParam mask, Soa4Vector3::InParam trueValue, Soa4Vector3::InParam falseValue )");

{
    Soa4Mask3 mask( CreateSoa4MaskScalar( true, false, true, false), 
        CreateSoa4MaskScalar( false, true, false, true ), 
        CreateSoa4MaskScalar( false, false, true, true ) );
    Soa4Vector3 res = Select( mask, mA, mB );
    Soa4Vector3 ref( Soa4FloatFromFloats( -1.0f, 9.0f, 3.0f, -7.0f ), 
        Soa4FloatFromFloats( 5.0f, 3.0f, 4.0f, 1.0f ), 
        Soa4FloatFromFloats( 1.5f, -9.0f, 3.0f, -10.0f ));
    Validate( IsEqual( ref, res ) );
}

